def solve(arr):
    if not arr or not arr[0]: return -1
    n, m = len(arr), len(arr[0])
    max_row = -1
    j = m - 1
    for i in range(n):
        while j >= 0 and arr[i][j] == 1:
            j -= 1
            max_row = i
    return max_row

