solution_python:
def solve(n):
    moves = []
    val = int(n)
    def hanoi(d, src, dest, aux):
        if d == 1:
            moves.append(f'{src} {dest}')
            return
        hanoi(d-1, src, aux, dest)
        moves.append(f'{src} {dest}')
        hanoi(d-1, aux, dest, src)
    hanoi(val, 1, 3, 2)
    return str(len(moves)) + '\n' + '\n'.join(moves)

