import java.util.*;
public class Solution {
    private static List<String> moves;
    private static void hanoi(int d, int src, int dest, int aux) {
        if (d == 1) {
            moves.add(src + " " + dest);
            return;
        }
        hanoi(d - 1, src, aux, dest);
        moves.add(src + " " + dest);
        hanoi(d - 1, aux, dest, src);
    }
    public static String solve(Object nObj) {
        int n = Integer.parseInt(nObj.toString().trim());
        moves = new ArrayList<>();
        hanoi(n, 1, 3, 2);
        StringBuilder sb = new StringBuilder();
        sb.append(moves.size());
        for (String m : moves) {
            sb.append("\n").append(m);
        }
        return sb.toString();
    }
}

