public class Solution {
    public static String solve(Object nObj) {
        int n = Integer.parseInt(nObj.toString().trim());
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < (1 << n); i++) {
            int val = i ^ (i >> 1);
            String binary = Integer.toBinaryString(val);
            while (binary.length() < n) {
                binary = "0" + binary;
            }
            if (sb.length() > 0) sb.append("\n");
            sb.append(binary);
        }
        return sb.toString();
    }
}

