public class Solution {
    public static int solve(int[] scores, int k) {
        int threshold = scores[k - 1];
        int count = 0;
        for (int s : scores) {
            if (threshold <= 0) {
                if (s > 0) count++;
            } else {
                if (s >= threshold) count++;
            }
        }
        return count;
    }
}

