import java.util.*;
public class Solution {
    public static String solve(String s) {
        int[] counts = new int[256];
        for (char c : s.toCharArray()) counts[c]++;
        int oddCount = 0;
        char oddChar = 0;
        for (int i = 0; i < 256; i++) {
            if (counts[i] % 2 == 1) { oddCount++; oddChar = (char) i; }
        }
        if (oddCount > 1) return "NO SOLUTION";
        StringBuilder half = new StringBuilder();
        for (int i = 0; i < 256; i++) {
            for (int j = 0; j < counts[i] / 2; j++) half.append((char) i);
        }
        String left = half.toString();
        String mid = oddCount == 1 ? String.valueOf(oddChar) : "";
        return left + mid + half.reverse().toString();
    }
}

