def solve(target: list[int], m: int) -> int:
    n = len(target)
    S = set()

    for p in range(n):
        if target[p] > 0:
            k = target[p]
            if k > m:
                return -1
            l = p - k + 1
            if l < 0 or l > n - m:
                return -1
            S.add(l)

    if not S:
        if all(x == 0 for x in target):
            return 0
        return -1

    adj = {l: set() for l in S}
    in_degree = {l: 0 for l in S}

    for p in range(n):
        if target[p] == 0:
            l_min = max(0, p - m + 1)
            l_max = min(n - m, p)
            for l in range(l_min, l_max + 1):
                if l in S:
                    return -1
        else:
            k = target[p]
            l_req = p - k + 1
            l_min = max(0, p - m + 1)
            l_max = min(n - m, p)
            for l in range(l_min, l_max + 1):
                if l in S and l != l_req:
                    if l_req not in adj[l]:
                        adj[l].add(l_req)
                        in_degree[l_req] += 1

    queue = [l for l in S if in_degree[l] == 0]
    visited_count = 0

    while queue:
        u = queue.pop()
        visited_count += 1
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if visited_count == len(S):
        return len(S)
    else:
        return -1

